// Generate tests/fixtures/caps-swaptions.sexp from QuantLib: caps, floors and
// collars on EURIBOR 6M (BlackCapFloorEngine, BachelierCapFloorEngine) and
// European swaptions on vanilla swaps (BlackSwaptionEngine,
// BachelierSwaptionEngine), physical and cash (par yield curve) settled.
//
//   nix develop .#fixtures -c sh tests/fixtures/generate.sh
//
// Valued on 2026-09-24: EURIBOR 6M forecast on its curve, discounting on
// ESTR (fixture_curves.hpp). The file is (:caps (plist ...) :swaptions
// (plist ...)). Each cap entry lists, per volatility, the total and the
// optionlet prices.

#include "fixture_curves.hpp"

#include <ql/version.hpp>

#include <cstdio>
#include <string>
#include <vector>

using namespace QuantLib;
using fixture::iso;
using fixture::parseDate;
using fixture::today;

namespace {

struct VolSpec {
    std::string name;   // :black, :shifted-black, :normal, :black-per-expiry
    double vol, displacement;
};

void printPrices(FILE* out, const std::string& label, const CapFloor& capFloor) {
    auto prices = capFloor.result<std::vector<Real> >("optionletsPrice");
    std::fprintf(out, "    (%s %.17g (", label.c_str(), capFloor.NPV());
    for (Real p : prices) std::fprintf(out, "%.17g ", p);
    std::fprintf(out, "))\n");
}

}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s output.sexp\n", argv[0]);
        return 1;
    }
    Settings::instance().evaluationDate() = today;
    FILE* out = std::fopen(argv[1], "w");
    std::fprintf(out, ";;;; caps-swaptions.sexp --- generated by tests/fixtures/generate.sh from QuantLib %s\n",
                 QL_VERSION);
    fixture::Curves curves = fixture::buildCurves();
    auto euribor = ext::make_shared<Euribor6M>(curves.euriborHandle);

    // Per-expiry caplet vols (variance linear in time, flat vol beyond).
    std::vector<Date> expiryDates = {Date(24, March, 2027), Date(24, September, 2027),
                                     Date(25, September, 2028), Date(24, September, 2030)};
    std::vector<Volatility> expiryVols = {0.32, 0.28, 0.25, 0.22};
    auto perExpiryCurve = ext::make_shared<CapletVarianceCurve>(today, expiryDates, expiryVols,
                                                                Actual365Fixed());
    perExpiryCurve->enableExtrapolation();
    Handle<OptionletVolatilityStructure> perExpiry(perExpiryCurve);

    // ------------------------------------------------------------- caps
    struct CapSpec { std::string name, type; double capRate, floorRate, nominal; std::string start, end; };
    std::vector<CapSpec> caps = {
        {"5Y cap at 2.5%", ":cap", 0.025, 0, 1e6, "2026-09-28", "2031-09-29"},
        {"5Y floor at 1.8%", ":floor", 0, 0.018, 1e6, "2026-09-28", "2031-09-29"},
        {"1Y into 3Y cap at 2.2%", ":cap", 0.022, 0, 1e7, "2027-09-28", "2030-09-30"},
        {"3Y collar 2.6% / 1.7%", ":collar", 0.026, 0.017, 5e6, "2026-09-28", "2029-09-28"},
        {"10Y floor at 2.4%", ":floor", 0, 0.024, 1e6, "2026-09-28", "2036-09-29"}};
    std::vector<VolSpec> vols = {
        {":black", 0.25, 0.0}, {":shifted-black", 0.15, 0.01}, {":normal", 0.0085, 0.0},
        {":black-per-expiry", 0.0, 0.0}};
    std::fprintf(out, "(:per-expiry-vols (");
    for (Size i = 0; i < expiryDates.size(); ++i)
        std::fprintf(out, "(\"%s\" %.17g) ", iso(expiryDates[i]).c_str(), expiryVols[i]);
    std::fprintf(out, ")\n :caps\n (\n");
    for (const CapSpec& c : caps) {
        Schedule schedule(parseDate(c.start), parseDate(c.end), 6 * Months, TARGET(),
                          ModifiedFollowing, ModifiedFollowing, DateGeneration::Backward, false);
        Leg leg = IborLeg(schedule, euribor).withNotionals(c.nominal).withPaymentDayCounter(Actual360());
        CapFloor::Type type = c.type == ":cap" ? CapFloor::Cap
                              : c.type == ":floor" ? CapFloor::Floor : CapFloor::Collar;
        CapFloor capFloor(type, leg, std::vector<Rate>(1, c.capRate), std::vector<Rate>(1, c.floorRate));
        std::fprintf(out, "  (:name \"%s\" :type %s :cap-rate %.17g :floor-rate %.17g :nominal %.17g "
                          ":start \"%s\" :end \"%s\"\n   :prices (\n",
                     c.name.c_str(), c.type.c_str(), c.capRate, c.floorRate, c.nominal, c.start.c_str(),
                     c.end.c_str());
        for (const VolSpec& v : vols) {
            if (v.name == ":normal")
                capFloor.setPricingEngine(ext::make_shared<BachelierCapFloorEngine>(
                    curves.estrHandle, v.vol, Actual365Fixed()));
            else if (v.name == ":black-per-expiry")
                capFloor.setPricingEngine(ext::make_shared<BlackCapFloorEngine>(curves.estrHandle, perExpiry));
            else
                capFloor.setPricingEngine(ext::make_shared<BlackCapFloorEngine>(
                    curves.estrHandle, v.vol, Actual365Fixed(), v.displacement));
            printPrices(out, v.name, capFloor);
        }
        std::fprintf(out, "   ))\n");
    }
    std::fprintf(out, " )\n");

    // -------------------------------------------------------- swaptions
    struct SwaptionSpec {
        std::string name; bool payer; double rate, spread, nominal;
        std::string exercise, start, end;
    };
    std::vector<SwaptionSpec> swaptions = {
        {"1Y into 5Y payer at 2.5%", true, 0.025, 0.0, 1e6, "2027-09-24", "2027-09-28", "2032-09-28"},
        {"2Y into 10Y receiver at 2.8%", false, 0.028, 0.0, 1e7, "2028-09-25", "2028-09-27", "2038-09-27"},
        {"5Y into 5Y payer at 2.9%, spread 10bp", true, 0.029, 0.001, 1e6, "2031-09-24", "2031-09-26",
         "2036-09-26"},
        {"6M into 2Y receiver at 2.2%", false, 0.022, 0.0, 5e6, "2027-03-24", "2027-03-30", "2029-03-30"}};
    std::fprintf(out, " :swaptions\n (\n");
    for (const SwaptionSpec& s : swaptions) {
        Date start = parseDate(s.start), end = parseDate(s.end);
        Schedule fixed(start, end, 1 * Years, TARGET(), ModifiedFollowing, ModifiedFollowing,
                       DateGeneration::Backward, false);
        Schedule floating(start, end, 6 * Months, TARGET(), ModifiedFollowing, ModifiedFollowing,
                          DateGeneration::Backward, false);
        auto swap = ext::make_shared<VanillaSwap>(s.payer ? Swap::Payer : Swap::Receiver, s.nominal,
                                                  fixed, s.rate, Thirty360(Thirty360::BondBasis),
                                                  floating, euribor, s.spread, Actual360());
        auto exercise = ext::make_shared<EuropeanExercise>(parseDate(s.exercise));
        std::fprintf(out, "  (:name \"%s\" :type %s :fixed-rate %.17g :spread %.17g :nominal %.17g "
                          ":exercise \"%s\" :start \"%s\" :end \"%s\"\n   :prices (\n",
                     s.name.c_str(), s.payer ? ":payer" : ":receiver", s.rate, s.spread, s.nominal,
                     s.exercise.c_str(), s.start.c_str(), s.end.c_str());
        for (int cash = 0; cash < 2; ++cash) {
            Swaption swaption(swap, exercise, cash ? Settlement::Cash : Settlement::Physical,
                              cash ? Settlement::ParYieldCurve : Settlement::PhysicalOTC);
            const char* settlement = cash ? ":cash-annuity" : ":physical";
            swaption.setPricingEngine(ext::make_shared<BlackSwaptionEngine>(
                curves.estrHandle, 0.20, Actual365Fixed(), 0.0));
            std::fprintf(out, "    (%s :black %.17g)\n", settlement, swaption.NPV());
            swaption.setPricingEngine(ext::make_shared<BlackSwaptionEngine>(
                curves.estrHandle, 0.12, Actual365Fixed(), 0.02));
            std::fprintf(out, "    (%s :shifted-black %.17g)\n", settlement, swaption.NPV());
            swaption.setPricingEngine(ext::make_shared<BachelierSwaptionEngine>(
                curves.estrHandle, 0.0080, Actual365Fixed()));
            std::fprintf(out, "    (%s :normal %.17g)\n", settlement, swaption.NPV());
        }
        std::fprintf(out, "   ))\n");
    }
    std::fprintf(out, " ))\n");
    std::fclose(out);
    return 0;
}
